# region: fold
def fold(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: render
def render(xs, factor=2):
    return [v * factor for v in xs]

# region: gather
def gather(xs, offset=1):
    return [v - offset for v in xs]

# region: digest
def digest(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: intake
def intake(summary, name='beta'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return intake(digest(gather(render(fold(raw)))))

